insert into skills (id, strand, sequence, name, objective) values
  ('L1', 'literacy', 1, 'Letter names & sounds', 'Match a spoken letter sound to the written letter.'),
  ('L2', 'literacy', 2, 'Blending sounds into simple words (CVC)', 'Blend 3–4 separate sounds into a simple word such as c-a-t.'),
  ('L3', 'literacy', 3, 'Common word recognition', 'Recognise high-frequency words by sight.'),
  ('L4', 'literacy', 4, 'Reading short sentences (accuracy & pace)', 'Read a short sentence aloud with at least 90% accuracy.'),
  ('L5', 'literacy', 5, 'Literal comprehension of a short passage', 'Answer who/what/where questions about a 3-sentence passage.'),
  ('L6', 'literacy', 6, 'Inference & vocabulary in context', 'Work out feelings or word meanings from clues in a sentence.'),
  ('N1', 'numeracy', 1, 'Number recognition 0–20', 'Match a spoken number from 0 to 20 to its written numeral.'),
  ('N2', 'numeracy', 2, 'Counting & quantity to 20', 'Count a set of up to 20 objects and say how many.'),
  ('N3', 'numeracy', 3, 'Addition within 20', 'Add two numbers with a total of 20 or less.'),
  ('N4', 'numeracy', 4, 'Subtraction within 20', 'Subtract within 20.'),
  ('N5', 'numeracy', 5, 'Place value (tens and ones to 99)', 'Explain the value of each digit in a 2-digit number.'),
  ('N6', 'numeracy', 6, 'Simple word problems (one step)', 'Solve a one-step add or subtract story problem within 20.')
